import{_ as i,a0 as s,w as a,s as l,ao as p,I as n,x as o,a1 as r,A as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"安卓编年史（18）：Android 4.0 冰淇淋三明治—摩登时代 | LCTT x X-CMD","titleTemplate":false,"description":"安卓编年史（18）：Android 4.0 冰淇淋三明治—摩登时代 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓编年史（18）：Android 4.0 冰淇淋三明治—摩登时代 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓编年史（18）：Android 4.0 冰淇淋三明治—摩登时代 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/19 - The history of Android","title":"安卓编年史（18）：Android 4.0 冰淇淋三明治—摩登时代","tag":"The history of Android","desc":""},"relativePath":"The history of Android/19 - The history of Android.md","filePath":"[post].md"}'),u={name:"The history of Android/19 - The history of Android.md"};function m(f,t,g,x,T,A){const e=s("Link");return a(),l("div",null,[t[19]||(t[19]=p('<h1 id="安卓编年史-18-android-4-0-冰淇淋三明治—摩登时代" tabindex="-1">安卓编年史（18）：Android 4.0 冰淇淋三明治—摩登时代 <a class="header-anchor" href="#安卓编年史-18-android-4-0-冰淇淋三明治—摩登时代" aria-label="Permalink to “安卓编年史（18）：Android 4.0 冰淇淋三明治—摩登时代”">​</a></h1><h3 id="android-4-0-冰淇淋三明治-——-摩登时代" tabindex="-1">Android 4.0 冰淇淋三明治 —— 摩登时代 <a class="header-anchor" href="#android-4-0-冰淇淋三明治-——-摩登时代" aria-label="Permalink to “Android 4.0 冰淇淋三明治 —— 摩登时代”">​</a></h3><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/samsung-i9250-galaxy-nexus-51.jpg" alt="三星 Galaxy Nexus，安卓4.0的首发设备。"></p><p><em>三星 Galaxy Nexus，安卓4.0的首发设备。</em></p><p>安卓 4.0，冰淇淋三明治，在 2011 年 10 月发布，系统发布回到正轨，带来定期发布的手机和平板，并且安卓再次开源。这是自姜饼以来手机设备的第一个更新，意味着最主要的安卓用户群体近乎一年没有见到更新了。4.0 随处可见缩小版的蜂巢设计，还将虚拟按键，操作栏（Action Bar），全新的设计语言带到了手机上。</p><p>冰淇淋三明治在三星 Galaxy Nexus 上首次亮相，也是最早带有 720p 显示屏的安卓手机之一。随着分辨率的提高，Galaxy Nexus 使用了更大的 4.65 英寸显示屏——几乎比最初的 Nexus One 大了一整英寸。这被许多批评者认为“太大了”，但如今的安卓设备甚至更大。（5 英寸当今是“正常”的。）冰淇淋三明治比姜饼的性能要求更高，Galaxy Nexus 配备了一颗双核，1.2Ghz 德州仪器 OMAP 处理器和 1GB 的内存。</p><p>在美国，Galaxy Nexus 在 Verizon 首发并且支持 LTE。不像之前的 Nexus 设备，最流行的型号——Verizon 版——是在运营商的控制之下，谷歌的软件和更新在手机得到更新之前要经过 Verizon 的核准。这导致了更新的延迟以及 Verizon 不喜欢的应用被移除，即便是 Google Wallet 也不例外。</p><p>多亏了冰淇淋三明治的软件改进，谷歌终于达成了移除手机上按钮的目标。有了虚拟导航键，实体电容按钮就可以移除了，最终 Galaxy Nexus 仅有电源和音量是实体按键。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/2home.png" alt="安卓 4.0 将很多蜂巢的设计缩小了。"></p><p><em>安卓 4.0 将很多蜂巢的设计缩小了。 [Ron Amadeo 供图]</em></p><p>电子质感的审美在蜂巢中显得有点多。于是在冰淇淋三明治中，谷歌开始减少科幻风的设计。科幻风的时钟字体从半透明折叠风格转变成纤细，优雅，看起来更加正常的字体。解锁环的水面波纹效果被去除了，蜂巢中的外星风格时钟小部件也被极简设计所取代。系统按钮也经过了重新设计，原先的蓝色轮廓，偶尔的厚边框变成了细的，设置带有白色轮廓。默认壁纸从蜂巢的蓝色太空船内部变成条纹状，破碎的彩虹，给默认布局增添了不少迟来的色彩。</p><p>蜂巢的系统栏在手机上一分为二。在顶上是传统的状态栏，底部是新的系统栏，放着三个系统按钮：后退、主屏幕、最近应用。一个固定的搜索栏放置在了主屏幕顶部。该栏以和底栏一样的方式固定在屏幕上，所以在五个主屏上，它总共占据了 20 个图标大小的位置。在蜂巢的锁屏上，内部的小圆圈可以向大圆圈外的任意位置滑动来解锁设备。在冰淇淋三明治，你得把小圆圈移动到解锁图标上。这个新准确度要求允许谷歌向锁屏添加新的选项：一个相机快捷方式。将小圆圈拖向相机图标会直接启动相机，跳过了主屏幕。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/appsandnotic40.png" alt="一个手机系统意味着更多的应用，通知面板重新回到了全屏界面。"></p><p><em>一个手机系统意味着更多的应用，通知面板重新回到了全屏界面。 [Ron Amadeo 供图]</em></p><p>应用抽屉还是标签页式的，但是蜂巢中的“我的应用”标签被“部件”标签页替代，这是个简单的 2×3 部件略缩图视图。像蜂巢里的那样，这个应用抽屉是分页的，需要水平滑动换页。（如今安卓仍在使用这个应用抽屉设计。）应用抽屉里新增的是 Google+ 应用，后来独立存在。还有一个“Messenger”快捷方式，是 Google+ 的私密信息服务。（不要混淆 “Messenger” 和已有的 “Messaging” 短信应用。）</p><p>因为我们现在回到了手机上，所以短信，新闻和天气，电话，以及语音拨号都回来了，以及 Cordy，一个平板的游戏，被移除了。尽管不是 Nexus 设备，我们的截图还是来自 Verizon 版的设备，可以从图上看到有像 “My Verizon Mobile” 和 “VZ Backup Assistant” 这样没用的应用。为了和冰淇淋三明治的去电子风格主题一致，日历和相机图标现在看起来更像是来自地球的东西而不是来自外星球。时钟，下载，电话，以及安卓市场同样得到了新图标，“联系人”获得了新图标，还有新名字 “People”。</p>',16)),n("p",null,[t[1]||(t[1]=o("通知面板进行了大改造，特别是和",-1)),r(e,{href:"http://cdn.arstechnica.net/wp-content/uploads/2014/02/32.png"},{default:d(()=>[...t[0]||(t[0]=[o("之前姜饼中的设计",-1)])]),_:1}),t[2]||(t[2]=o("相比而言。面板头部有个日期，一个设置的快捷方式，以及“清除所有”按钮。虽然蜂巢的第一个版本就允许用户通过通知右边的“X”消除单个通知，但是冰淇淋三明治的实现更加优雅：只要从左向右滑动通知即可。蜂巢有着蓝色高亮，但是蓝色色调到处都是。冰淇淋三明治几乎把所有地方的蓝色统一成一个（如果你想知道确定的值，hex 码是 ",-1)),t[3]||(t[3]=n("code",null,"#33B5E5",-1)),t[4]||(t[4]=o("）。通知面板的背景是透明的，底部的“把手”变为一个简单的小蓝圈，带着不透明的黑色背景。",-1))]),t[20]||(t[20]=n("p",null,[n("img",{src:"http://cdn.arstechnica.net/wp-content/uploads/2014/03/market.png",alt:"安卓市场的主页背景变成了黑色。"})],-1)),t[21]||(t[21]=n("p",null,[n("em",null,"安卓市场的主页背景变成了黑色。 [Ron Amadeo 供图]")],-1)),t[22]||(t[22]=n("p",null,"市场获得了又一个新设计。它终于再次支持纵向模式，并且添加了音乐到商店中，你可以从中购买音乐。新的市场拓展了从蜂巢中引入的卡片概念，它还是第一个同时使用在手机和平板上的版本。主页上的卡片通常不是链接到应用的，而是指向特别的促销页面，像是“编辑精选”或季度促销。",-1)),t[23]||(t[23]=n("hr",null,null,-1)),t[24]||(t[24]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2016/05/r.amadeo-45843.jpg",alt:"Ron Amadeo"})],-1)),n("p",null,[r(e,{href:"http://arstechnica.com/author/ronamadeo"},{default:d(()=>[...t[5]||(t[5]=[o("Ron Amadeo",-1)])]),_:1}),t[7]||(t[7]=o(" / Ron是Ars Technica的评论编缉，专注于安卓系统和谷歌产品。他总是在追寻新鲜事物，还喜欢拆解事物看看它们到底是怎么运作的。",-1)),r(e,{href:"https://twitter.com/RonAmadeo"},{default:d(()=>[...t[6]||(t[6]=[o("@RonAmadeo",-1)])]),_:1})]),t[25]||(t[25]=n("hr",null,null,-1)),n("p",null,[t[9]||(t[9]=o("via: ",-1)),r(e,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/19/"},{default:d(()=>[...t[8]||(t[8]=[o("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/19/",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=o("译者：",-1)),r(e,{href:"https://github.com/alim0x"},{default:d(()=>[...t[10]||(t[10]=[o("alim0x",-1)])]),_:1}),t[13]||(t[13]=o(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:d(()=>[...t[11]||(t[11]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=o("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...t[14]||(t[14]=[o("LCTT",-1)])]),_:1}),t[17]||(t[17]=o(" 原创翻译，",-1)),r(e,{href:"http://linux.cn/"},{default:d(()=>[...t[15]||(t[15]=[o("Linux中国",-1)])]),_:1}),t[18]||(t[18]=o(" 荣誉推出",-1))])])}const N=i(u,[["render",m]]);export{C as __pageData,N as default};
